from google import genai

def select_platform_resource(model_name: str, project_id: str, location: str):
    # In genai, the model is selected directly during content generation,
    # but this function can return a representation of the selected model.
    # For simplicity, we'll return a dictionary with the model name and client configuration.
    return {
        "model_id": model_name,
        "client_config": {
            "project_id": project_id,
            "location": location
        }
    }

from google import genai

def collect_platform_metadata(payload, config):
    with genai.Client(vertexai=True, project=config["project_id"], location=config["location"]) as client:
        response = client.models.generate_content(model=config["model_id"], contents=payload["text"])
    return {"text": response.text or "", "usage_metadata": response.usage_metadata.to_dict() if response.usage_metadata else {}}

from google import genai

def get_model_client(project_id: str, location: str):
    return genai.Client(vertexai=True, project=project_id, location=location)

class ModelRequest:
    def __init__(self, text: str):
        self.text = text

    def to_dict(self):
        return {"text": self.text}

class ModelResponse:
    def __init__(self, text: str, metadata: dict = None):
        self.text = text
        self.metadata = metadata if metadata is not None else {}

    def to_dict(self):
        return {"text": self.text, "metadata": self.metadata}

from google import genai

def check_platform_output_safety(payload, config):
    with genai.Client(vertexai=True, project=config["project_id"], location=config["location"]) as client:
        response = client.models.generate_content(model=config["model_id"], contents=payload["text"])

    safety_attributes = []
    if response.candidates:
        for candidate in response.candidates:
            if candidate.safety_ratings:
                for rating in candidate.safety_ratings:
                    safety_attributes.append(rating.to_dict())

    return {"text": response.text or "", "safety_attributes": safety_attributes}

from google.cloud import translate_v3 as translate

def localized_platform_output(text: str, target_language: str, project_id: str):
    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "mime_type": "text/plain",
            "target_language_code": target_language,
        }
    )

    translated_text = ""
    if response.translations:
        translated_text = response.translations[0].translated_text

    return {"original_text": text, "translated_text": translated_text, "target_language": target_language}

from google import genai

def platform_output_embedding(text: str, project_id: str, location: str):
    with genai.Client(vertexai=True, project=project_id, location=location) as client:
        # Using an embedding model, for example, 'text-embedding-004'
        embedding_model = client.get_model("text-embedding-004")
        response = embedding_model.embed_content(content=text)

    embedding = []
    if response.embedding: 
        embedding = response.embedding.values

    return {"text": text, "embedding": embedding}
